package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

var (
	secretKey []byte
)

func init() {
	k := os.Getenv("SECRET_KEY")
	if k == "" {
		log.Fatal("SECRET_KEY environment variable is required")
	}
	secretKey = []byte(k)
}

type TokenStore struct {
	mu     sync.Mutex
	tokens map[string]*TokenEntry
}

type TokenEntry struct {
	UserID    string
	Role      string
	Token     string
	Refreshes int
	ExpiresAt time.Time
	Revoked   bool
}

type RefreshRequest struct {
	CurrentToken  string `json:"current_token"`
	RequestedRole string `json:"requested_role,omitempty"`
}

type RefreshResponse struct {
	NewToken  string `json:"new_token"`
	ExpiresAt string `json:"expires_at"`
}

var store = &TokenStore{
	tokens: make(map[string]*TokenEntry),
}

func generateToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("failed to generate token: %w", err)
	}
	return hex.EncodeToString(b), nil
}

func computeMAC(userID, role, token string) string {
	mac := hmac.New(sha256.New, secretKey)
	mac.Write([]byte(fmt.Sprintf("%s:%s:%s", userID, role, token)))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyMAC(userID, role, token, expectedMAC string) bool {
	actualMAC := computeMAC(userID, role, token)
	return hmac.Equal([]byte(actualMAC), []byte(expectedMAC))
}

// refreshToken handles the token refresh atomically
func (s *TokenStore) refreshToken(currentToken string, requestedRole string) (*TokenEntry, string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Step 1: Read current token state
	entry, exists := s.tokens[currentToken]
	if !exists {
		return nil, "", fmt.Errorf("token not found")
	}

	// Step 2: Validate token state
	if entry.Revoked {
		return nil, "", fmt.Errorf("token revoked")
	}

	if time.Now().After(entry.ExpiresAt) {
		return nil, "", fmt.Errorf("token expired")
	}

	if entry.Refreshes >= 5 {
		return nil, "", fmt.Errorf("max refreshes exceeded")
	}

	// Step 3: Determine the role for the new token
	// Only admins can request role elevation during refresh
	newRole := entry.Role
	if requestedRole != "" && requestedRole != entry.Role {
		if entry.Role != "admin" {
			return nil, "", fmt.Errorf("insufficient privileges for role change")
		}
		newRole = requestedRole
	}

	// Step 4: Revoke old token atomically
	entry.Revoked = true

	// Step 5: Issue new token with validated role
	newToken, err := generateToken()
	if err != nil {
		return nil, "", err
	}
	mac := computeMAC(entry.UserID, newRole, newToken)
	newEntry := &TokenEntry{
		UserID:    entry.UserID,
		Role:      newRole,
		Token:     newToken,
		Refreshes: entry.Refreshes + 1,
		ExpiresAt: time.Now().Add(15 * time.Minute),
		Revoked:   false,
	}
	s.tokens[newToken] = newEntry

	return newEntry, mac, nil
}

// issueNewToken creates and stores a new token
func (s *TokenStore) issueNewToken(userID, role string, refreshCount int) (*TokenEntry, string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	newToken, err := generateToken()
	if err != nil {
		return nil, "", err
	}
	mac := computeMAC(userID, role, newToken)
	entry := &TokenEntry{
		UserID:    userID,
		Role:      role,
		Token:     newToken,
		Refreshes: refreshCount,
		ExpiresAt: time.Now().Add(15 * time.Minute),
		Revoked:   false,
	}
	s.tokens[newToken] = entry
	return entry, mac, nil
}

func handleRefresh(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req RefreshRequest
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1024)).Decode(&req); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	if req.CurrentToken == "" {
		http.Error(w, "token required", http.StatusBadRequest)
		return
	}

	newEntry, mac, err := store.refreshToken(req.CurrentToken, req.RequestedRole)
	if err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	resp := RefreshResponse{
		NewToken:  fmt.Sprintf("%s.%s", newEntry.Token, mac),
		ExpiresAt: newEntry.ExpiresAt.Format(time.RFC3339),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var creds struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1024)).Decode(&creds); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// Simplified auth - in production use bcrypt + DB lookup
	var role string
	switch creds.Username {
	case "alice":
		if creds.Password != "alice_pass" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		role = "user"
	case "bob":
		if creds.Password != "bob_pass" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		role = "admin"
	default:
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	entry, mac, err := store.issueNewToken(creds.Username, role, 0)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	resp := RefreshResponse{
		NewToken:  fmt.Sprintf("%s.%s", entry.Token, mac),
		ExpiresAt: entry.ExpiresAt.Format(time.RFC3339),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/login", handleLogin)
	http.HandleFunc("/refresh", handleRefresh)
	http.ListenAndServe(":8080", nil)
}
